#[path = "solution.rs"]
mod solution;

use std::collections::BTreeMap;
use solution::{LinkGraph, natural_join, normalize_locator, render_list_map, render_string_list, render_string_map, source_nodes};

#[test]
fn normalizes_local_and_explicit_locators() {
    assert_eq!(normalize_locator("folder/file"), Ok("local:folder/file".to_string()));
    assert_eq!(normalize_locator("a:b:c"), Ok("a:b:c".to_string()));
    assert_eq!(normalize_locator("git+ssh-1.2:repo"), Ok("git+ssh-1.2:repo".to_string()));
}

#[test]
fn rejects_empty_whitespace_and_invalid_schemes() {
    for input in ["", "a b", " a:b", "a:b\n", ":value", "1abc:value", "ab_c:value", "ab/value:x"] {
        assert!(normalize_locator(input).is_err(), "accepted {input:?}");
    }
}

#[test]
fn natural_join_handles_all_slice_sizes_without_mutation() {
    let empty: Vec<String> = vec![];
    assert_eq!(natural_join(&empty), "");

    let values = vec!["alpha".to_string(), "beta".to_string(), "gamma".to_string(), "delta".to_string()];
    let original = values.clone();
    assert_eq!(natural_join(&values[..1]), "alpha");
    assert_eq!(natural_join(&values[..2]), "alpha and beta");
    assert_eq!(natural_join(&values[..3]), "alpha, beta, and gamma");
    assert_eq!(natural_join(&values), "alpha, beta, gamma, and delta");
    assert_eq!(values, original);
}

#[test]
fn source_nodes_are_distinct_ordered_and_consider_all_incoming_edges() {
    let candidates = vec!["b", "a", "b", "c", "d", "e"].into_iter().map(str::to_string).collect::<Vec<_>>();
    let original = candidates.clone();
    let mut outgoing = BTreeMap::new();
    outgoing.insert("outside".to_string(), vec!["a".to_string()]);
    outgoing.insert("b".to_string(), vec!["c".to_string()]);
    outgoing.insert("d".to_string(), vec!["d".to_string(), "not-a-candidate".to_string()]);
    let graph = LinkGraph { outgoing };

    assert_eq!(source_nodes(&candidates, &graph), vec!["b".to_string(), "e".to_string()]);
    assert_eq!(candidates, original);
}

#[test]
fn source_nodes_with_empty_graph_preserve_first_occurrences() {
    let candidates = vec!["x".to_string(), "x".to_string(), "y".to_string()];
    let graph = LinkGraph { outgoing: BTreeMap::new() };
    assert_eq!(source_nodes(&candidates, &graph), vec!["x".to_string(), "y".to_string()]);
}

#[test]
fn renders_compact_json_with_required_escaping_and_stable_order() {
    let mut strings = BTreeMap::new();
    strings.insert("z".to_string(), "line\nnext\r\t\\\"".to_string());
    strings.insert("a".to_string(), "plain".to_string());
    assert_eq!(render_string_map(&strings), "{\"a\":\"plain\",\"z\":\"line\\nnext\\r\\t\\\\\\\"\"}");

    let values = vec!["q\"".to_string(), "slash\\".to_string(), "\n".to_string()];
    let original = values.clone();
    assert_eq!(render_string_list(&values), "[\"q\\\"\",\"slash\\\\\",\"\\n\"]");
    assert_eq!(values, original);

    let mut lists = BTreeMap::new();
    lists.insert("b".to_string(), vec!["2".to_string(), "1".to_string()]);
    lists.insert("a".to_string(), Vec::new());
    assert_eq!(render_list_map(&lists), "{\"a\":[],\"b\":[\"2\",\"1\"]}");
}

#[test]
fn empty_rendering_inputs_are_compact() {
    assert_eq!(render_string_map(&BTreeMap::new()), "{}");
    assert_eq!(render_list_map(&BTreeMap::new()), "{}");
    assert_eq!(render_string_list(&[]), "[]");
}

